package com.example.gameworkbench.service.impl;
import com.example.gameworkbench.analytics.PromptMetricRow; import com.example.gameworkbench.mapper.ModelCallMetricMapper; import com.example.gameworkbench.service.PromptVersionAnalyticsService; import com.example.gameworkbench.vo.analytics.PromptVersionMetricVO; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*; import java.math.BigDecimal;
@Service @RequiredArgsConstructor public class PromptVersionAnalyticsServiceImpl implements PromptVersionAnalyticsService { private final ModelCallMetricMapper mapper;
 public List<PromptVersionMetricVO> metrics(Long userId,Long projectId,String agentType,LocalDateTime from,LocalDateTime to,boolean includeMock){ if(userId==null) throw new IllegalArgumentException("userId required"); if(!from.isBefore(to)) throw new IllegalArgumentException("invalid window"); return mapper.selectAnalyticsRows(userId,projectId,agentType,from,to).stream().filter(r->includeMock||"FALSE".equals(r.getMockState())).collect(java.util.stream.Collectors.groupingBy(PromptMetricRow::getPromptVersionId)).entrySet().stream().map(e->aggregate(e.getKey(),e.getValue())).toList(); }
 private PromptVersionMetricVO aggregate(Long id,List<PromptMetricRow> rows){ long real=rows.stream().filter(r->"FALSE".equals(r.getMockState())).count(),mock=rows.stream().filter(r->"TRUE".equals(r.getMockState())).count(),unknown=rows.size()-real-mock; long success=rows.stream().filter(r->"SUCCESS".equals(r.getStatus())).count(); List<Long> lat=rows.stream().map(PromptMetricRow::getLatencyMs).filter(Objects::nonNull).sorted().toList(); long in=rows.stream().map(PromptMetricRow::getInputTokens).filter(Objects::nonNull).mapToLong(Integer::longValue).sum(),out=rows.stream().map(PromptMetricRow::getOutputTokens).filter(Objects::nonNull).mapToLong(Integer::longValue).sum(); BigDecimal cost=rows.stream().map(PromptMetricRow::getEstimatedCost).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add); return PromptVersionMetricVO.builder().promptVersionId(id).callCount(rows.size()).realSampleCount(real).mockSampleCount(mock).unknownMockCount(unknown).successRate(rows.isEmpty()?null:(double)success/rows.size()).meanLatencyMs(lat.isEmpty()?null:lat.stream().mapToLong(Long::longValue).average().orElseThrow()).p50LatencyMs(percentile(lat,.5)).p95LatencyMs(percentile(lat,.95)).latencyMissingCount(rows.size()-lat.size()).inputTokens(in).outputTokens(out).estimatedCost(cost).costMissingCount(rows.stream().filter(r->r.getEstimatedCost()==null).count()).insufficientSample(lat.size()<20).build(); }
 private Long percentile(List<Long> values,double p){return values.isEmpty()?null:values.get((int)Math.ceil(p*values.size())-1);}
}
